// Embeds prisma/migrations/*/migration.sql into the app bundle (src/lib/generated/migrations.ts),
// because some hosts (e.g. Hostinger) deploy only the build output without the prisma folder.
// Runs automatically before `next build`; the generated file is also committed.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const dir = path.join(process.cwd(), "prisma", "migrations");
const migrations = readdirSync(dir, { withFileTypes: true })
  .filter((d) => d.isDirectory() && existsSync(path.join(dir, d.name, "migration.sql")))
  .map((d) => d.name)
  .sort()
  .map((name) => ({ name, sql: readFileSync(path.join(dir, name, "migration.sql"), "utf8") }));
const out = `// Generated by scripts/embed-migrations.mjs — do not edit.\nexport const MIGRATIONS: { name: string; sql: string }[] = ${JSON.stringify(migrations, null, 2)};\n`;
const file = path.join(process.cwd(), "src", "lib", "generated", "migrations.ts");
if (!existsSync(file) || readFileSync(file, "utf8") !== out) writeFileSync(file, out);
console.log(`[embed-migrations] ${migrations.length} migration(s) embedded`);
